// === Tab: sketch ===
// https://openprocessing.org/sketch/2276640
// playing with randomly generated scribbly lines 
// makes some abstract impressionist-looking kind of creations

// line points are chosen or discarded depending on how much the pixel is already colored in
// in this one the palette is sorted by lightness value 
// and color for each line is chosen based on the length of the line 
// (long lines are darker, short lines are lighter) 
// we also redraw over the longest lines periodically & at the end, so they don't get lost

let lines
let g
let lastTime = 0
let bg
let gSize // graphics size
let rSize // rendered size

	// ['#533a71', '#454a96', '#6184d8', '#50c5b7', '#9cec5b', '#f0f465', '#ff4a1c', '#ed254e'],
	// ['#f9c80e', '#f86624', '#ea3546', '#662e9b', '#43bccd', '#232020'],
let palettes = [
	["#87425d", "#3c2e6b", "#0081af", "#a7d6c3", "#285943", "#8a8fbd", "#9a79b8", "#fcee49"],
	['#874286', '#856596', '#fc814a', '#f9c8ce', '#a8d7a8', '#b6cccc', '#8aadbc', '#7a7eb8'],
	['#99dfff', '#60ebca', '#c4f5ed', '#b8ccfc', '#04996d', '#4467ab'],
	['#f398c3', '#cf3895', '#a0d28d', '#06b4b0', '#fed000', '#FF8552'],
]
let palette = []

function setSizesAndColors() {
	palette = [...random(palettes)]
	palette.sort((a, b) => chroma(b).get('hsl.l') - chroma(a).get('hsl.l'))
	let col = chroma(random(palette))

	bg1 = col.hex()
	bg2 = col.set('hsl.l', 0.9).hex()
	rSize = min(floor(max(width, height) * 0.8), 700)
	gSize = floor(rSize * 0.7)
}

function setup() {
	createCanvas(windowWidth, windowHeight)
	setSizesAndColors()
	g = createGraphics(gSize, gSize)
	let pd = Math.min(pixelDensity(), 2)

	lines = new Lines(g, pd, palette)
}

function draw() {
	let ms = millis()
	let delta = ms - lastTime
	lastTime = ms

	let done = lines.update(delta)
	push()
	translate((width - rSize) / 2, (height - rSize) / 2)

	background(palette[palette.length - 1])
	noStroke()
	fill(255, 200)
	rect(0, 0, rSize, rSize)
	image(g, 0, 0, rSize, rSize)
	pop()
}

function windowResized() {
	resizeCanvas(window.innerWidth, window.innerHeight)
	sz = floor(max(width, height) * 0.7)
}

function mousePressed() {
	lines.reset()
	setSizesAndColors()
	g.resizeCanvas(gSize, gSize)
	lines = new Lines(g, min(pixelDensity(), 2), palette)
}

// === Tab: lines ===
function distSq(p1, p2) {
    return Math.pow(p1[0] - p2[0], 2) + Math.pow(p1[1] - p2[1], 2)
}

class Lines {
    constructor(g, pixelDensity, palette) {
        this.g = g
        this.width = g.width
        this.height = g.height
        this.pixelDensity = pixelDensity
        this.longLineMinSq = Math.pow(this.width * 0.08, 2)
        this.g.pixelDensity(pixelDensity)
        this.g.loadPixels()
        this.palette = palette

        this.stepRate = 5000
        this.wiggle = {
            withinLine: 2,
            onLinePointFail: 0.6,
            betweenLine: 2.5,
            max: 2.2,
        }
        this.imprecision = 5
        this.len = {
            minStart: 15,
            minEnd: 7,
            minCur: 20,
            maxReal: this.width * 4,
            maxColor: this.width * 1.5,
        }
        this.lengths = []
        this.currentLineLength = 0
        this.stepMult = 1
        this.alphaThreshold = 210
        this.colorMove = 0.00009
        this.stopAtFails = 1000
        this.lineWidth = 3

        this.currentLine = []
        this.linesDrawn = 0
        this.lastPoint = null
        this.longLines = []
        this.longLinesSaved = []
        this.redrawnCount = 0
        this.redrawing = false
        this.angle = Math.random() * Math.PI * 2
        this.lineAngle = this.angle
        this.done = false
        this.doneAdding = false
        this.colorIndex = 0
        this.failsCount = 0
        this.lineLookPoint = [
            floor(random(this.width * 0.4, this.width * 0.6)),
            floor(random(this.height * 0.4, this.height * 0.6)),
        ]
    }

    getPxIndex(x, y) {
        return (y * this.width * this.pixelDensity + x) * 4 * this.pixelDensity
    }

    getBlankPixelNear(cx, cy, radius) {
        let tries = 0
        let rangeX = [cx - radius, cx + radius]
        let rangeY = [cy - radius, cy + radius]
        if (rangeX[0] < 0) rangeX[0] = 0
        if (rangeX[1] >= this.width) rangeX[1] = this.width - 1
        if (rangeY[0] < 0) rangeY[0] = 0
        if (rangeY[1] >= this.height) rangeY[1] = this.height - 1

        while (tries < 10) {
            let [x, y] = [floor(random(rangeX[0], rangeX[1])), floor(random(rangeY[0], rangeY[1]))]
            if (this.isBlankIshPx(x, y)) {
                return [x, y]
            }
            tries++
        }

        return false
    }

    isBlankIshPx(x, y) {
        let ind = this.getPxIndex(x, y)
        return this.g.pixels[ind + 3] < this.alphaThreshold
    }

    getLinePoints(x, y) {
        let curX = x
        let curY = y
        let points = []
        var tries = 0
        while (tries < 30 && points.length < this.len.maxReal) {
            let nextX = curX + Math.cos(this.lineAngle) * this.stepMult
            let nextY = curY + Math.sin(this.lineAngle) * this.stepMult

            if (!this.isBlankIshPx(Math.round(nextX), Math.round(nextY))) {
                this.lineAngle += random(
                    -this.wiggle.onLinePointFail * 0.5,
                    this.wiggle.onLinePointFail * 0.5
                )
                tries++
            } else if (nextX < 0 || nextX >= this.width || nextY < 0 || nextY >= this.height) {
                break
            } else {
                points.push([curX, curY])
                curX = nextX
                curY = nextY
                let angleDiff = this.lineAngle - this.angle
                if (Math.abs(angleDiff) > this.wiggle.max) {
                    if (angleDiff > 0) {
                        this.lineAngle -= random(this.wiggle.withinLine)
                    } else {
                        this.lineAngle += random(this.wiggle.withinLine)
                    }
                } else {
                    this.lineAngle += random(
                        this.wiggle.withinLine * -0.5,
                        this.wiggle.withinLine * 0.5
                    )
                }
                tries = 0
            }
        }

        if (points.length < this.len.minCur) {
            return false
        }

        return points
    }

    addFail() {
        this.failsCount++
        if (this.failsCount > 10 && this.longLines.length) {
            let longLine = this.longLines.shift()
            this.lineLookPoint = longLine[Math.floor(longLine.length / 2)]
        } else if (this.failsCount > 50) {
            this.lineLookPoint = [Math.floor(random(this.width)), Math.floor(random(this.height))]
        }
        if (this.failsCount > 500) {
            this.len.minCur = max(this.len.minCur - 2, this.len.minEnd)
        }
        if (this.failsCount > this.stopAtFails) {
            this.doneAdding = true
            this.longLinesSaved.sort((a, b) => b.length - a.length)
            this.redrawnCount = 0
        }
    }

    getLine() {
        let pixel = this.getBlankPixelNear(this.lineLookPoint[0], this.lineLookPoint[1], 50)
        if (!pixel) return false

        let [x1, y1] = pixel
        var points = this.getLinePoints(x1, y1)

        if (!points) return false

        if (distSq(points[0], points[points.length - 1]) > this.longLineMinSq) {
            this.longLines.push([...points])
            this.longLinesSaved.push([...points])
        }

        this.currentLine = points
        this.currentLineLength = points.length
        this.lengths.push(points.length)
        this.redrawing = false
        return true
    }

    finishLine() {
        this.linesDrawn++
        this.lastPoint = null
        this.g.loadPixels()
        this.currentLine = []
        if (this.linesDrawn % 100 === 0) {
            this.angle += random(this.wiggle.betweenLine * -0.5, this.wiggle.betweenLine * 0.5)
        }
        this.lineAngle = this.angle

        if (
            this.linesDrawn > 300 &&
            this.linesDrawn % 50 === 0 &&
            this.redrawnCount < this.longLinesSaved.length * 2
        ) {
            this.doRedraw()
        }
    }

    doRedraw() {
        this.currentLine = [...this.longLinesSaved[this.redrawnCount % this.longLinesSaved.length]]
        this.redrawnCount++
        this.redrawing = true
        this.currentLineLength = this.currentLine.length
    }

    lineStep() {
        if (this.currentLine.length < 2) return

        let [x1, y1] = this.lastPoint ?? this.currentLine[0]

        let len = this.currentLineLength
        let mix = Math.min(1, (len - this.len.minEnd) / (this.len.maxColor - this.len.minEnd))
        // mix = 1 - Math.pow(1 - mix, 4) // easeoutquart
        mix = 1 - Math.pow(1 - mix, 3) // easeoutcubic
        let color = chroma(this.palette[Math.floor(mix * (this.palette.length - 1))])
        this.g.stroke(color.hex())
        let lw = this.redrawing ? this.lineWidth * 0.75 : this.lineWidth
        this.g.strokeWeight(lw)
        this.g.drawingContext.shadowColor = color.alpha(0.36).hex()
        this.g.drawingContext.shadowBlur = this.lineWidth * 2.75

        let [x2, y2] = this.currentLine[1]
        // if (!this.redrawing) {
        //     let n = this.g.noise(x2 * 0.1, y2 * 0.1) * this.imprecision - this.imprecision / 2
        //     x2 += n
        //     y2 += n
        // }
        this.g.line(x1, y1, x2, y2)
        this.lastPoint = [x2, y2]
        this.currentLine.shift()
        if (this.currentLine.length < 2) {
            this.finishLine()
        }
    }

    update(delta) {
        let steps = Math.round((delta / 1000) * this.stepRate)
        while (steps > 0 && !this.done) {
            if (this.currentLine.length >= 2) {
                this.g.push()
                this.lineStep()
                this.g.pop()
                steps--
            } else {
                if (this.doneAdding) {
                    if (this.redrawnCount < this.longLinesSaved.length) {
                        this.doRedraw()
                    } else {
                        this.done = true
                    }
                } else {
                    if (!this.getLine()) {
                        this.addFail()
                    } else {
                        this.failsCount = 0
                    }
                }
            }
        }

        return this.done
    }

    reset() {
        this.g.clear()
        this.g.loadPixels()
        this.linesDrawn = 0
        this.done = false
        this.doneAdding = false
        this.currentLine = []
        this.longLines = []
        this.failsCount = 0
        this.angle = Math.random() * Math.PI * 2
        this.len.minCur = this.len.minStart
    }
}

